    VALUES (2, 60, 1, DATE '2026-11-16', 'Amostragem, média, desvio-padrão e cartas de controle para acompanhar a estabilidade de um processo.', '/assets/imagens/banner-ava.png', 'Hibrido', 'Estatística na Qualidade', 'estatistica para controle de qualidade estatistica na qualidade', 'Estatística para Controle de Qualidade', 'Inspetores de qualidade, líderes de produção e técnicos de processo.', 'estatistica-controle-qualidade', 'EmBreve');
