    VALUES (4, 80, 2, NULL, 'Leitura de manuais, fichas técnicas e telas de equipamentos em inglês, com vocabulário do setor industrial.', '/assets/imagens/hero-image.png', 'Presencial', 'Inglês Instrumental', 'ingles instrumental para a industria ingles instrumental', 'Inglês Instrumental para a Indústria', 'Operadores e técnicos que lidam com manuais e equipamentos importados.', 'ingles-instrumental-industria', 'Encerrado');
