    VALUES (6, 36, 3, DATE '2027-02-01', 'Força, torque, energia e potência para entender o funcionamento e a eficiência de máquinas industriais.', '/assets/imagens/video-thumb.png', 'Ead', 'Física Aplicada', 'fisica aplicada a maquinas e equipamentos fisica aplicada', 'Física Aplicada a Máquinas e Equipamentos', 'Trabalhadores da manutenção e da operação de máquinas.', 'fisica-aplicada-maquinas', 'EmBreve');
