    VALUES (7, 20, 4, NULL, 'Princípios da economia circular, ciclo de vida do produto e exemplos de redução de desperdício na produção.', '/assets/imagens/hero-image.png', 'Ead', 'Economia Circular', 'economia circular na industria economia circular', 'Economia Circular na Indústria', 'Qualquer pessoa interessada em sustentabilidade no ambiente de trabalho.', 'economia-circular-industria', 'InscricoesAbertas');
