    VALUES (8, 64, 4, NULL, 'Classificação de resíduos, logística reversa e ações de eficiência energética com retorno mensurável.', '/assets/imagens/banner-ava.png', 'Hibrido', 'Gestão de Resíduos', 'gestao de residuos e eficiencia energetica gestao de residuos', 'Gestão de Resíduos e Eficiência Energética', 'Supervisores, técnicos de meio ambiente e membros de comissões internas.', 'gestao-residuos-eficiencia-energetica', 'Encerrado');
